// A battery end label that would sit on the 0% / 100% axis mark only repeats the axis.
const pctLabel = v => { const r = Math.round(v); return r >= 100 || r <= 0 ? null : `${r}%` }
const CSTATE = { conforming: ['pill-ok', 'On track'], drifting: ['pill-warn', 'Drifting'], silent: ['', 'Not reporting'], untyped: ['', 'No test declared'] }
const statusBadge = st => <span className={`pill ${{ declared: 'pill-run', confirmed: 'pill-ok', inferred: 'pill-warn', unclassified: '', none: '' }[st]}`}>{STATUS[st].label}</span>

const RECENT_H = 6 // a cycle that ended this recently is still shown, with its results

/** One icon beside "Battery": a bolt while most devices charge, a down arrow while they drain. */
function ChargeIcon({ state }) {
  if (!state) return null
  const tip = `${state.charging ? 'Charging' : 'Discharging'} now · ${state.on} on charge, ${state.off} on battery`
  return (
    <span className={`charge-icon ${state.charging ? 'is-charging' : 'is-draining'}`} title={tip} aria-label={tip} role="img">
      {state.charging
        ? <svg viewBox="0 0 16 16" width="18" height="18" aria-hidden="true"><path d="M9.2 1.5 3.5 9h3.7l-.9 5.5L12.5 7H8.7z" fill="currentColor" /></svg>
        : <svg viewBox="0 0 16 16" width="18" height="18" aria-hidden="true"><path d="M8 2.5v9M4.2 8 8 11.8 11.8 8" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round" /></svg>}
    </span>
  )
}

// The bench: every device not on a firmware test, plus firmware-test devices the bench's cycle names by serial (the user, 11 Nov 2026:
// the whole lab on one Reproducing Boot Loop cycle).
const benchDevices = (allDev, fwTests, decl, now) => allDev.filter(d => !onFwTest(fwTests, d.serial, now) || (decl?.group?.kind === 'serials' && (decl.group.serials || []).includes(d.serial)))

// Several cycles at once (the user, 10 Nov 2026: the bench, plus cycles only for firmware-test devices): tick which to show, a full section each, the
// bench first, the firmware tests' table last. Opens on the cycle with the most devices.
export default function TodayView({ fleet }) {
  const fwTests = useSyncExternalStore(subscribeFw, getFw, getFw)
  const planSync = useSyncExternalStore(subscribePlan, getPlanSync, getPlanSync)
  const win = useSyncExternalStore(subscribeWindow, getWindow, getWindow)
  const auto = useAutomations() // what the lab laptop runs on its own: shown on the WLC and Ads tiles
  useEffect(() => { loadWindow(fleet.DEV) }, [fleet.DEV])
  useEffect(() => startPhoneSync(), []) // shared Today notes (data/phone.json)
  useEffect(() => startRoomSync(), [])  // the room's temperature from the lab's ESP32-S3 + SHT30, every minute
  const now = Date.now()
  const sides = useMemo(() => {
    const all = DECLS(), fwOnly = d => !testType(d.testType)?.idle && testType(d.testType)?.expect !== 'charge' && !benchDecls([d]).length
    return [...cyclesOn(all, dayKey(now - 24 * H)), ...cyclesOn(all, todayKey())].filter(c => fwOnly(c.decl) && c.startMs <= now && now - c.endMs <= RECENT_H * H)
  }, [fwTests, planSync.v, todayKey(), Math.floor(now / MIN), win.at2])
  const [ticked, setTicked] = useState(null) // null until someone ticks: the default below, which follows the cycles as they change
  const benchCycle = cycleAt(benchDecls(DECLS()), now), benchDev = benchDevices(fleet.DEV.filter(d => onBenchAt(d.serial, now)), fwTests, benchCycle?.decl, now)
  const choices = [
    { id: 'bench', tt: benchCycle && testType(benchCycle.decl.testType), n: benchCycle ? activeSerials(benchCycle.decl, benchDev, now).length : benchDev.length, side: null },
    ...sides.map(c => ({ id: c.decl.id, tt: testType(c.decl.testType), n: activeSerials(c.decl, fleet.DEV, now).length, side: c })),
  ]
  const largest = choices.reduce((a, b) => (b.n > a.n ? b : a)) // on a tie, the earlier one: the bench
  const kept = (ticked || []).filter(id => choices.some(c => c.id === id))
  const shown = kept.length ? kept : [largest.id]
  const toggle = id => setTicked(shown.includes(id) ? shown.filter(x => x !== id) : [...shown, id])
  const waiting = !win.at && !Object.keys(win.rows || {}).length && !win.err // still loading: the bench's section says so
  return (
    <div className="view-stack today-sections">
      {choices.length > 1 && !waiting && (
        <div className="cycle-picker" role="group" aria-label="Cycles to show">
          <span className="cycle-picker-title">Show cycles</span>
          {choices.map(c => {
            const on = shown.includes(c.id), only = on && shown.length === 1
            return (
              <label key={c.id} className={`cycle-pick${on ? ' on' : ''}`} title={only ? 'At least one cycle stays shown' : undefined}>
                <input type="checkbox" checked={on} disabled={only} onChange={() => toggle(c.id)} />
                <span className="cycle-pick-dot" style={{ background: c.tt ? `var(--tt-${ttSlot(c.tt.id)})` : 'var(--border-strong)' }} />
                {c.tt?.name || 'Bench'} <span className="secondary">· {c.n} device{c.n === 1 ? '' : 's'}</span>
              </label>
            )
          })}
        </div>
      )}
      {waiting ? <CycleSection fleet={fleet} auto={auto} side={null} />
        : choices.filter(c => shown.includes(c.id)).map(c => <CycleSection key={c.id} fleet={fleet} auto={auto} side={c.side} />)}
      {/* each iPhone's battery, whatever runs today (the user, 13 Nov 2026): in the bench's section, or here when that isn't shown */}
      {!waiting && !shown.includes('bench') && <IphonesNow now={now} />}
      <FwTestsToday fleet={fleet} />
    </div>
  )
}

/** One cycle on Today. side = null: the bench (whatever is running on it); else a cycle only for firmware-test devices. */
function CycleSection({ fleet, side, auto }) {
  const { allCycles, opts } = fleet
  // a device removed on the Summary screen is off Today from that day on (the user, 13 Nov 2026)
  const allDev = useMemo(() => fleet.DEV.filter(d => onBenchAt(d.serial)), [fleet.DEV, todayKey()])
  // a device on a firmware test is not part of the bench (the user, 6 Nov 2026): not in today's charge or cycle
  const fwTests = useSyncExternalStore(subscribeFw, getFw, getFw)
  const now = Date.now()
  const [planRev, setPlanRev] = useState(0) // bumped after a take-out / put-back, to re-read the plan
  const planSync = useSyncExternalStore(subscribePlan, getPlanSync, getPlanSync) // shared plan changed elsewhere
  const benchDecl = side ? null : cycleAt(benchDecls(DECLS()), now)?.decl
  const DEV = useMemo(() => (side ? allDev.filter(d => side.decl.group.serials.includes(d.serial)) : benchDevices(allDev, fwTests, benchDecl, Date.now())), [allDev, fwTests, side?.decl.id, benchDecl?.id, benchDecl?.mod])
  const win = useSyncExternalStore(subscribeWindow, getWindow, getWindow)

  // The day whose run is on now. A run planned 10:00 → 04:00 belongs to the day it started,
  // so until yesterday's overnight window closes (and today's has not opened) Today stays
  // on yesterday's run.
  const dayFor = k => {
    const ran = allCycles.filter(c => dayKey(c.start) === k).length
    const r = resolveDay(k, { decls: DECLS(), rota: ROTA(), ran, devices: DEV.length })
    const src = r.decl || r.rota || null
    return { ...r, key: k, tt: testType(r.testType), src, ran, serials: groupSerials(src && src.group, DEV), ...windowOn(k, src) }
  }
  // Each device's charge now (latest reading ≤ 15 min old and on charge): since when (the start
  // of its current stretch on charge) and from what level. Every charge since 25 Sep is a
  // Charging Cycle with no plan entry (adapt.js), so with no planned test running and most
  // devices on charge, Today shows that Charging Cycle (the lab, Oct 2026).
  const charges = useMemo(() => {
    const out = new Map(); let reporting = 0
    for (const d of DEV) {
      const r = rowsFor(d.serial); const last = r[r.length - 1]
      if (!last || now - Date.parse(last.timestamp) > 15 * MIN) continue
      reporting++
      if (!last.extra?.charging) continue
      // the charge began at the bottom of the last discharge: walking back from now the level
      // only falls (or holds at full, where it wobbles 99–100 and the flag flips) until that low,
      // then rises again by more than 2 points going further back (the discharge before it)
      let low = r.length - 1
      for (let j = r.length - 2; j >= 0; j--) {
        if (Date.parse(r[j + 1].timestamp) - Date.parse(r[j].timestamp) > 2 * H) break
        if (r[j].battery_pct < r[low].battery_pct) low = j
        else if (r[j].battery_pct > r[low].battery_pct + 2) break
      }
      out.set(d.serial, { t: Date.parse(r[low].timestamp), pct: r[low].battery_pct, now: last.battery_pct, at: Date.parse(last.timestamp) })
    }
    return { by: out, reporting }
  }, [DEV, win.at2])
  const chargingMost = charges.reporting > 0 && charges.by.size * 2 > charges.reporting
  // A bench off the charger with no test planned yet (the Auto plan names it once it can tell,
  // e.g. after ~1.5 h of load): each discharging device's run began at the last top of its
  // level — walking back from now it rises to that top (holding there while it sat on the
  // charger) and then falls by more than 2 points going further back (the charge before).
  const bench = useMemo(() => {
    const starts = []
    for (const d of DEV) {
      const r = rowsFor(d.serial); const last = r[r.length - 1]
      if (!last || now - Date.parse(last.timestamp) > 15 * MIN || last.extra?.charging) continue
      // just off the charger (still at 100 %, nothing dropped yet): the charger flag's last switch-off
      let k = r.length - 1
      while (k > 0 && !r[k - 1].extra?.charging && Date.parse(r[k].timestamp) - Date.parse(r[k - 1].timestamp) <= 30 * MIN) k--
      if (k > 0 && r[k - 1].extra?.charging && r[k - 1].battery_pct >= 90 && now - Date.parse(r[k].timestamp) < 20 * H) { starts.push(Date.parse(r[k].timestamp)); continue }
      let top = r.length - 1
      for (let j = r.length - 2; j >= 0; j--) {
        if (Date.parse(r[j + 1].timestamp) - Date.parse(r[j].timestamp) > 2 * H) break
        if (r[j].battery_pct > r[top].battery_pct) top = j
        else if (r[j].battery_pct < r[top].battery_pct - 2) break
      }
      if (r[top].battery_pct >= 90 && r[top].battery_pct - last.battery_pct >= 1) starts.push(Date.parse(r[top].timestamp))
    }
    if (starts.length < 3) return null
    const mid = median(starts), near = starts.filter(t => Math.abs(t - mid) <= 3 * H)
    return near.length >= 3 && now - mid < 20 * H ? { start: mid, n: near.length } : null
  }, [DEV, win.at2])
  // shared Today notes (data/phone.json): the iPhone readings, and take-outs made before the test is known
  const phoneDb = useSyncExternalStore(subscribePhone, getPhone, getPhone)
  // the room's temperature from the lab's ESP32-S3 + SHT30 (server/room.mjs), every minute
  const roomDb = useSyncExternalStore(subscribeRoom, getRoom, getRoom)
  const T = useMemo(() => {
    if (side) { const src = DECLS().find(d => d.id === side.decl.id) || side.decl // this copy changes on a take-out or a note
      return { ...dayFor(side.key), testType: src.testType, tt: testType(src.testType), decl: src, src,
      serials: activeSerials(src, DEV, now), removed: removedFrom(src), startMs: side.startMs, endMs: side.endMs, overnight: side.overnight, cycleNo: 1, cycleCount: 1 } }
    const decls0 = benchDecls(DECLS())
    if (!cycleAt(decls0, now) && !chargingMost && bench) {
      // running, but no test on the plan for it yet: timed from when the bench came off the charger.
      // Devices taken out already (held in data/phone.json until there is a plan entry) leave it.
      const k = dayKey(bench.start), out = pendingOuts(phoneDb, k), gone = new Set(out.map(r => r.serial))
      return { key: k, running: true, status: 'unclassified', testType: null, tt: null, src: null, decl: null, pendingOut: true,
        serials: DEV.map(d => d.serial).filter(s => !gone.has(s)), removed: out, startMs: bench.start, endMs: now + H, overnight: false, cycleNo: 1, cycleCount: 1 }
    }
    // Back on charge = the cycle is over, whatever window the plan gives it (the user, 30 Oct 2026: a Restaurant Case
    // planned to 02:29 still showed at 21:21, its devices on charge since ~20:30). A planned cycle running now gives way
    // to the Charging Cycle once most devices went on charge at least an hour after it started.
    const runningNow = cycleAt(decls0, now)
    const chargeStarts = [...charges.by.values()].map(c => c.t)
    // (cycleAt also returns a cycle starting within 2 h: not started yet, so the devices on charge are still the Charging Cycle — 6 Nov 2026)
    // (not in a test that charges by design: Reproducing Boot Loop)
    const backOnCharge = chargingMost && !testType(runningNow?.decl.testType)?.span && (!runningNow || now < runningNow.startMs || median(chargeStarts) > runningNow.startMs + H)
    if (backOnCharge) {
      const starts = chargeStarts
      return { key: todayKey(), charging: true, status: 'inferred', testType: 'charging', tt: testType('charging'), src: null, decl: null,
        serials: [...charges.by.keys()], removed: [], startMs: median(starts), endMs: now + H, overnight: false, cycleNo: 1, cycleCount: 1 }
    }
    // A day can hold several cycles. Show the one running now (including yesterday's still
    // going past midnight), else one that ended in the last RECENT_H (its results stay up until
    // the next starts — at 00:06 a cycle planned to 00:04 is "just ended", not "no test set"),
    // else the next one to start today, else today's last one.
    const decls = benchDecls(DECLS()), todays = cyclesOn(decls, todayKey())
    const recent = [...cyclesOn(decls, dayKey(now - 24 * H)), ...todays]
      .filter(c => c.endMs <= now && now - c.endMs <= RECENT_H * H).sort((a, b) => a.endMs - b.endMs).pop() || null
    const next = todays.find(c => c.startMs > now)
    const pick = cycleAt(decls, now) || (recent && (!next || next.startMs - now > RECENT_H * H) ? recent : null) || next || todays[todays.length - 1] || null
    if (!pick) return dayFor(todayKey())
    const base = dayFor(pick.key), src = pick.decl
    return { ...base, testType: src.testType, tt: testType(src.testType), decl: src, src,
      // devices taken out of this cycle leave its charts and table from the moment they left
      serials: activeSerials(src, DEV, now), removed: removedFrom(src), startMs: pick.startMs, endMs: pick.endMs, overnight: pick.overnight,
      cycleNo: cyclesOn(decls, pick.key).findIndex(c => c.decl.id === src.id) + 1, cycleCount: cyclesOn(decls, pick.key).length }
  }, [DEV, allCycles, win.at2, todayKey(), planRev, planSync.v, chargingMost, bench?.start, phoneDb, side?.decl.id, side?.endMs])
  // Take out works before the test is known too (the user, 27 Oct 2026): held for the bench, then
  // moved onto the plan entry as soon as one names the cycle (Auto, or a person on the Cycle plan)
  const canOut = !!T.decl || !!T.pendingOut
  useEffect(() => {
    if (!T.decl || side) return // held for the bench's cycle
    const held = pendingOuts(phoneDb, T.key); if (!held.length) return
    const have = new Set((T.decl.removed || []).map(r => r.serial))
    for (const r of held) { if (!have.has(r.serial)) takeOut(GROUP, T.decl.id, r); setPendingOut(T.key, r.serial, null) }
    setPlanRev(v => v + 1)
  }, [T.decl?.id, T.key, phoneDb])
  // a note written before the test was known goes onto the plan entry once there is one (added after any note it has)
  useEffect(() => {
    if (!T.decl || side) return
    const held = pendingNote(phoneDb, T.key); if (!held) return
    const cur = T.decl.note || ''
    if (!cur.includes(held)) setCycleNote(GROUP, T.decl.id, cur ? `${cur}\n${held}` : held)
    setPendingNote(T.key, '')
    setPlanRev(v => v + 1)
  }, [T.decl?.id, T.key, phoneDb])
  const key = T.key
  const ended = T.tt && T.endMs < now // the cycle shown has finished (the last one, until the next starts)
  // charging or discharging right now: what most of the cycle's devices report on their latest
  // reading (not the cycle's end — after a cycle the devices are back on charge)
  const chargeNow = (() => {
    let on = 0, off = 0
    for (const sn of T.serials) { const r = rowsFor(sn); const last = r[r.length - 1]; if (!last || now - Date.parse(last.timestamp) > 15 * MIN) continue; if (last.extra?.charging) on++; else off++ }
    return on + off === 0 ? null : { charging: on > off, on, off }
  })()
  const [takingOut, setTakingOut] = useState(null) // serial whose take-out form is open

  const winTo = Math.min(now, T.endMs)
  const conf = useMemo(() => T.serials.map(s => conform(s, T.tt?.span ? null : T.tt, T.startMs, winTo, { ended: T.endMs < now })), [T, win.at2])
  const reporting = conf.filter(c => c.state !== 'silent')
  const conforming = conf.filter(c => c.state === 'conforming')
  const drifting = conf.filter(c => c.state === 'drifting')

  // Each device's own run: when it came off the charger and how fast it is draining. The
  // window opens when the plan says (07:00); the run starts when someone pulls the devices.
  const coarse = useMemo(() => conf.filter(c => c.rows?.length).map(c => ({ c,
    // from 2 h before the window, so a device pulled early (09:46 for a 10:00 window) is seen leaving the charger
    // with no test and no run on the bench there is no run to time (it found last night's cycle's tail)
    start: T.tt?.span || (!T.tt && !T.running) ? null : runStartOf(rowsFor(c.serial).filter(r => { const t = Date.parse(r.timestamp); return t >= T.startMs - 2 * H && t <= winTo })) })), [conf])
    // then pin each switch-off to the minute between the last reading on charge and the first off it
  const [refineRev, setRefineRev] = useState(0)
  useEffect(() => { let live = true
    refineStarts(coarse.map(x => ({ serial: x.c.serial, start: x.start }))).then(n => { if (live && n) setRefineRev(v => v + 1) })
    return () => { live = false } }, [coarse])
  const runs = useMemo(() => new Map(coarse.map(({ c, start: s0 }) => {
    const start = refinedStart(c.serial, s0) || s0
    return [c.serial, { start, rows: c.rows, rate: drainSince(c.rows, start), split: drainSplit(c.rows, start), now: c.rows[c.rows.length - 1].battery_pct }]
  })), [coarse, refineRev])
  const all = [...runs.values()], started = all.filter(r => r.start)
  const runStart = T.tt?.span ? T.startMs : started.length ? median(started.map(r => r.start.t)) : null
  const nows = all.map(r => r.now), medNow = nows.length ? median(nows) : null
  const rates = started.map(r => r.rate).filter(v => v != null && v > 0)
  // a drain needs a few devices behind it: one device 20 min in is not the bench's rate (it put
  // "Reaches 20 %" three days away at the start of a run)
  const rate = rates.length >= Math.min(3, Math.max(1, Math.ceil(started.length / 2))) ? median(rates) : null
  // the same split by what the T7 was doing (WLC active / inactive / ads only), in the Drain rate
  // tile's drop-down; the same few-devices rule for each
  const enough = (xs) => xs.length >= Math.min(3, Math.max(1, Math.ceil(started.length / 2)))
  const splitOf = (k) => { const xs = started.map(r => r.split?.[k]).filter(v => v != null && v > 0); return { n: xs.length, rate: enough(xs) ? median(xs) : null } }
  // The lab's daily run goes back on charge at 15–25%, so 20% is "the run is done".
  const END_BAND = 20
  // devices still on the charger after the cycle started (the user, 4 Nov 2026: 00485 / 00606 / 00790 stayed on charge an
  // hour into the cycle and nobody noticed): a discharge cycle running for 10 min+, the device reporting and charging now
  const cycleOn = !T.charging && (T.running || T.decl) && T.startMs != null && now - T.startMs >= 10 * MIN && now < (T.endMs ?? Infinity)
  const stillCharging = cycleOn && !T.tt?.span ? (T.serials || []).filter(sn => { const d = fleet.DMAP.get(sn); return d && online(d) && d.snap?.charging }).sort(byBenchOrder) : []
  const stillSet = new Set(stillCharging)
  // Devices today: drain with / without WLC for a test that places a load on the pad (or a test not named yet) — the user, 2 Nov 2026
  // Reproducing Boot Loop: how many times each device was rebooted, counted by the lab (the user, 11 Nov 2026)
  const rebootCol = !!T.tt?.span && !!T.decl
  const padCols = !T?.charging && (!T?.tt || T.tt.loadHours || ['wlc_load', 'load_only', 'wlc_phone', 'market'].includes(T.tt.id))
  // Reached N %: while a "WLC off at ≤ N %" rule runs on the lab laptop, when each device first read N % or less since it
  // left the charger (the user, 4 Nov 2026: today's WLC on Load, load until 15 %, then WLC off — the boot-loop repro)
  // only in WLC on Load (the user, 14 Nov 2026: not in Ads only — no load there for the rule to switch off)
  const reachPct = !T.charging && T.tt?.id === 'wlc_load' && auto.rules?.length ? Math.max(...auto.rules.map(x => x.pct)) : null
  const reachAt = r => { if (reachPct == null || !r?.start || !r.rows) return null
    for (const x of r.rows) { const t = Date.parse(x.timestamp); if (t >= r.start.t && !x.empty && x.battery_pct != null && x.battery_pct <= reachPct) return t }
    return null }
  const etaEnd = rate && medNow > END_BAND ? now + (medNow - END_BAND) / rate * H : null
  const etaEmpty = rate && medNow > 0 ? now + medNow / rate * H : null
  // time first, then a short date when it isn't the cycle's day ("04:41 AM Nov 4"), like the big value
  const when = t => (dayKey(t) === key ? hm(t) : `${hm(t)} ${new Date(t).toLocaleDateString([], { month: 'short', day: 'numeric' })}`)
  // Start the charts half an hour before the run so the drop-off is visible, not four
  // hours of a flat line at 100% while the devices sat on the charger.
  // the charts start when the cycle did: the bench off the charger that day (10:00, not the plan's 07:00 or 30 min
  // before), or the charge's start; each day's own start, so it moves with the day's cycle (the user, 21 Oct 2026)
  const chartFrom = T.charging ? T.startMs : runStart || T.startMs
  // charging: each device's %/h since its charge began, and when the median reaches 95 %
  const chRates = T.charging ? [...charges.by.values()].map(c => (c.at - c.t) / H >= 1 / 3 ? (c.now - c.pct) / ((c.at - c.t) / H) : null).filter(v => v != null && v > 0) : []
  const chRate = chRates.length ? median(chRates) : null
  const FULL = 95, full = T.charging ? [...charges.by.values()].filter(c => c.now >= FULL).length : 0
  const etaFull = chRate && medNow != null && medNow < FULL ? now + (FULL - medNow) / chRate * H : null


  // Which devices the two charts show. null = every device (the default); a Set narrows
  // both charts at once. Colours come from the full sorted list, so a device keeps its
  // colour whatever else is ticked — the same rule T7's own device picker follows.
  const [picked, setPicked] = useState(null)
  const sorted = useMemo(() => [...T.serials].sort(), [T.serials.join(',')])
  const styleOf = useMemo(() => buildStyleMap(sorted), [sorted])
  const colorOf = useMemo(() => new Map([...styleOf].map(([k, v]) => [k, v.color])), [styleOf])
  const isOn = sn => picked == null || picked.has(sn)
  const toggle = sn => setPicked(p => {
    const n = new Set(p ?? sorted); n.has(sn) ? n.delete(sn) : n.add(sn)
    return n.size === sorted.length ? null : n
  })
  // Search narrows the charts and the table to matching serials ("044" finds …00044).
  const [query, setQuery] = useState('')
  const q = query.trim().toLowerCase()
  const matches = sn => !q || sn.toLowerCase().includes(q)
  const [listOpen, setListOpen] = useState(false)
  const [outOpen, setOutOpen] = useState(false) // Taken out of this cycle, closed by default
  const [putting, setPutting] = useState(null), putTimer = useRef(null) // Put back armed for this serial
  const [listQ, setListQ] = useState('') // search inside the Devices today list
  const listShown = listOpen || !!q
  // A device clicked in the table is ticked alone in the two charts above (Every device),
  // and the page scrolls up to them; clicking it again ticks every device again.
  const chartsRef = useRef(null)
  // a taken-out device clicked in "Taken out of this cycle" is charted alone too (its readings, not in the cycle's list)
  const outPicked = picked ? [...picked].filter(sn => !conf.some(c => c.serial === sn) && (T.removed || []).some(r => r.serial === sn))
    .map(sn => ({ serial: sn, rows: rowsFor(sn), state: 'silent' })) : []
  const shown = [...conf, ...outPicked].filter(c => c.rows?.length && isOn(c.serial) && matches(c.serial))
  const few = shown.length <= 4 // few enough to label every line by name

  const lastOf = c => c.rows[c.rows.length - 1].battery_pct
  const lo = shown.length ? shown.reduce((a, b) => lastOf(b) < lastOf(a) ? b : a) : null
  const hi = shown.length ? shown.reduce((a, b) => lastOf(b) > lastOf(a) ? b : a) : null
  // the device in the middle by battery now (the median one), beside the lowest and highest
  const mid = shown.length ? [...shown].sort((a, b) => lastOf(a) - lastOf(b))[Math.floor((shown.length - 1) / 2)] : null
  const ptsOf = (c, pick = r => r.battery_pct) => c.rows.filter(r => Date.parse(r.timestamp) >= chartFrom && pick(r) != null)
    .map(r => ({ x: Date.parse(r.timestamp), y: pick(r) }))
  // Each chart can show every ticked device or their average; both open on the average (the
  // lab's choice, Oct 2026). Clicking a device in the table switches to Every device with it.
  const [battMode, setBattMode] = useState('avg')
  const [tempMode, setTempMode] = useState('avg')
  const MODES = [{ id: 'avg', label: 'Average' }, { id: 'all', label: 'Every device' }]
  const only = picked != null && picked.size === 1 ? [...picked][0] : null
  const focusDevice = sn => {
    if (only === sn) { setPicked(null); return }
    setPicked(new Set([sn])); setBattMode('all'); setTempMode('all')
    chartsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }
  const selSerials = shown.map(c => c.serial)
  const avg = a => a.reduce((x, y) => x + y, 0) / a.length
  const battAvg = useMemo(() => buckets(selSerials, chartFrom, winTo, r => r.battery_pct, avg), [selSerials.join(','), chartFrom, win.at2])
  const battMin = useMemo(() => buckets(selSerials, chartFrom, winTo, r => r.battery_pct, a => Math.min(...a)), [selSerials.join(','), chartFrom, win.at2])
  const battMax = useMemo(() => buckets(selSerials, chartFrom, winTo, r => r.battery_pct, a => Math.max(...a)), [selSerials.join(','), chartFrom, win.at2])
  const tAvg = useMemo(() => buckets(selSerials, chartFrom, winTo, temp, avg), [selSerials.join(','), chartFrom, win.at2])

  // The projection starts from the line actually drawn: the average in Average mode, the
  // median of the ticked devices otherwise, at their median drain rate.
  const selRuns = shown.map(c => runs.get(c.serial)).filter(Boolean)
  const selRates = selRuns.filter(r => r.start && r.rate > 0).map(r => r.rate)
  const selRate = selRates.length ? median(selRates) : null
  const selNow = battMode === 'avg' ? (battAvg.length ? battAvg[battAvg.length - 1].y : null)
    : (selRuns.length ? median(selRuns.map(r => r.now)) : null)
  const selEmpty = selRate && selNow > 0 ? now + selNow / selRate * H : null
  // no drain to project when every shown device is back on the charger
  const allCharging = shown.length > 0 && shown.every(c => fleet.DMAP.get(c.serial)?.snap?.charging)
  const projTo = selRate && selNow != null && T.endMs > now && !allCharging ? Math.min(T.endMs, selEmpty || T.endMs) : null
  const projection = projTo ? [{ x: now, y: selNow }, { x: projTo, y: Math.max(0, selNow - selRate * (projTo - now) / H) }] : []
  const projSeries = projection.length ? [{ id: 'projected', label: 'Projected', pts: projection, color: 'var(--text-3)', width: 1.6, dash: '2 4', smooth: false, endLabel: `${Math.round(projection[1].y)}%`, labelColor: 'var(--text-3)' }] : []
  const tail = sn => '…' + sn.slice(-5)

  const series = battMode === 'avg'
    ? [
        { id: 'max', label: 'Highest', pts: battMax, color: 'var(--series-8)', width: 1.25, opacity: .8, dash: '3 3', endLabel: battMax.length ? pctLabel(battMax[battMax.length - 1].y) : null, labelColor: 'var(--series-8)', onLabel: hi && (() => focusDevice(hi.serial)), labelTitle: hi && `${hi.serial} · show it alone` },
        { id: 'min', label: 'Lowest', pts: battMin, color: 'var(--series-3)', width: 1.25, opacity: .8, dash: '3 3', endLabel: battMin.length ? pctLabel(battMin[battMin.length - 1].y) : null, labelColor: 'var(--series-3)', onLabel: lo && (() => focusDevice(lo.serial)), labelTitle: lo && `${lo.serial} · show it alone` },
        { id: 'avg', label: 'Average', pts: battAvg, color: 'var(--series-1)', width: 2.4, endLabel: battAvg.length ? pctLabel(battAvg[battAvg.length - 1].y) : null, onLabel: mid && (() => focusDevice(mid.serial)), labelTitle: mid && `Middle device ${mid.serial} (${lastOf(mid)}%) · show it alone` },
      ]
    : [
        ...shown.map(c => {
          const drift = c.state === 'drifting'
          return { id: c.serial, label: tail(c.serial) + (drift ? ' · drifting' : ''), pts: ptsOf(c), color: colorOf.get(c.serial), width: drift ? 2.8 : 1.5, opacity: few || drift ? 1 : .8,
            dash: styleOf.get(c.serial)?.dash,
            endLabel: few ? `${c.serial.slice(-4)} ${lastOf(c)}%` : (c === lo || c === hi) ? pctLabel(lastOf(c)) : null }
        }),
      ]
  // the room's own temperature (ESP32-S3 + SHT30 on the lab laptop, server/roomSerial.mjs) as one more line, so a
  // battery running hot can be told from a warm room (the user, 2 Nov 2026)
  const roomPts = useMemo(() => {
    const sensors = (roomDb.sensors || []).filter(x => x.rows?.length)
    const x = sensors.find(x => x.id === 'room') || sensors[0]
    return x ? x.rows.filter(r => r[0] >= chartFrom && r[0] <= winTo + 5 * MIN).map(r => ({ x: r[0], y: r[1] })) : []
  }, [roomDb, chartFrom, winTo])
  const roomSeries = roomPts.length > 1 ? [{ id: 'room', label: 'Room', pts: roomPts, color: 'var(--text-secondary)', width: 1.8, dash: '6 4',
    endLabel: `room ${roomPts[roomPts.length - 1].y.toFixed(0)}°`, labelColor: 'var(--text-secondary)' }] : []
  const tempSeries = [...roomSeries, ...(tempMode === 'avg'
    ? [
        { id: 'avg', label: 'Average', pts: tAvg, color: 'var(--series-1)', width: 2, endLabel: tAvg.length ? `avg ${tAvg[tAvg.length - 1].y.toFixed(0)}°` : null },
      ]
    : shown.map(c => {
        const pts = ptsOf(c, temp), last = pts[pts.length - 1]
        return { id: c.serial, label: tail(c.serial), pts, color: colorOf.get(c.serial), dash: styleOf.get(c.serial)?.dash, width: 1.6,
          endLabel: last && (few || last.y >= TEMP_WARN) ? `${c.serial.slice(-4)} ${last.y.toFixed(0)}°` : null }
      }))]
  // Tooltip rows in T7's style; the busiest charts list the six most relevant lines.
  const battTip = (t, hits) => {
    const rows = hits.filter(h => h.p).sort((a, b) => a.p.y - b.p.y)
    const top = rows.length > 6 ? [...rows.slice(0, 3), ...rows.slice(-3)] : rows
    return tooltipHtml(hm(t), top.map(({ s, p }) => ({ color: s.color, name: s.label || s.id, value: `${Math.round(p.y)}%` })))
      + (rows.length > 6 ? `<div class="tt-time" style="margin:4px 0 0">+${rows.length - 6} more between</div>` : '')
  }
  const tempTip = (t, hits) => {
    // the room always shows, first; the devices after it, hottest first
    const room = hits.filter(h => h.p && h.s.id === 'room')
    const rows = hits.filter(h => h.p && h.s.id !== 'room').sort((a, b) => b.p.y - a.p.y)
    return tooltipHtml(hm(t), [...room, ...rows.slice(0, 6)].map(({ s, p }) => ({ color: s.color, name: s.label || s.id, value: `${p.y.toFixed(1)} °C` })))
      + (rows.length > 6 ? `<div class="tt-time" style="margin:4px 0 0">+${rows.length - 6} more, all cooler</div>` : '')
  }
  const picker = <DevicePicker serials={sorted} picked={picked} colorOf={colorOf} styleOf={styleOf} drifting={new Set(drifting.map(d => d.serial))}
    onToggle={toggle} onAll={() => setPicked(null)} onNone={() => setPicked(new Set())}
    onSet={set => setPicked(set.size === sorted.length ? null : set)} />
  const noneTicked = picked != null && picked.size === 0
  const silent = T.serials.length - reporting.length
  // no readings in this browser yet: which cycle is running can't be told, so say "loading"
  // rather than "No test set · Not started" for the seconds until they come (the user, 26 Oct 2026)
  const waiting = !win.at && !Object.keys(win.rows || {}).length && !win.err

  if (side && waiting) return null // the bench's section says it is still loading
  return (
    <div className="view-stack">
      <div className="card" style={{ borderLeft: `3px solid ${T.tt ? `var(--tt-${ttSlot(T.tt.id)})` : 'var(--border-strong)'}` }}>
        <div className="card-body today-head">
        <div className="today-head-main">
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', fontSize: 11.5, letterSpacing: '.04em', color: 'var(--text-3)', fontWeight: 600 }}>
            {dayLong(key)} {waiting ? <span className="pill">Loading</span> : T.charging ? <span className="pill pill-ok">On charge</span> : T.running ? <span className="pill pill-run">Running</span> : statusBadge(T.status)}
            {ended ? <span className="pill">Ended {when(T.endMs)}</span> : null}
            <span className={`pill ${reporting.length ? 'pill-run pill-live' : ''}`}>Live · {reporting.length} device{reporting.length === 1 ? '' : 's'} reporting</span>
          </div>
          <h1 style={{ margin: '6px 0 4px', fontSize: 26, lineHeight: 1.15 }}>{waiting ? <><span className="spin" style={{ width: 18, height: 18, verticalAlign: 0 }} /> Finding today's cycle…</> : T.tt ? T.tt.name : T.running ? <>Cycle running <span className="secondary" style={{ fontSize: 16, fontWeight: 500 }}>· test not known yet</span></> : 'No test set'}{T.cycleCount > 1 ? <span className="secondary" style={{ fontSize: 14, fontWeight: 500 }}> · cycle {T.cycleNo} of {T.cycleCount}</span> : null}</h1>
          <div className="secondary" style={{ fontSize: 12.5 }}>
            {waiting ? <>Reading the devices' last 7 days from the MDM; the cycle, its tiles and charts show once they are in.</>
              : T.charging ? <>Every device back on charge counts as a Charging Cycle, no plan entry needed · {charges.by.size} of {charges.reporting} reporting devices charging</>
              : T.tt ? <>{T.source === 'rota' ? 'From the standing weekly rota' : T.src?.auto ? <>Added automatically from the readings<PlanSource decl={T.src} /></> : <>Planned{T.src?.by ? <> by <b>{T.src.by}</b></> : null}{T.src?.at ? ` at ${hm(T.src.at)}` : ''}</>}
              {' '}· {T.serials.length} devices · window {hm(T.startMs)}–{hm(T.endMs)}{T.overnight ? ' next day' : ''}</>
              : T.running ? <>{bench.n} devices came off the charger around {hm(T.startMs)}. The Auto plan names the test from the readings once it can tell (a load on the pad for ~1.5 h, or none) — or <a className="link" href="#/nx/plan">set it on the Cycle plan</a>.</>
              : <>The MDM can't tell which test is running. <a className="link" href="#/nx/plan">Set one on the Cycle plan</a>.</>}
          </div>
          {/* a note on this cycle, for the record (shared with the plan; shown on its test screen too) */}
          {T.decl && !waiting && <CycleNote key={T.decl.id} decl={T.decl} onSaved={() => setPlanRev(v => v + 1)} />}
          {!T.decl && T.pendingOut && !waiting && <CycleNote key={'held' + T.key} note={pendingNote(phoneDb, T.key)} onSave={text => setPendingNote(T.key, text)} onSaved={() => {}} />}
        </div>
        </div>
      </div>

      {/* readings that did not come for some devices: said here, retried by itself */}
      {!side && <PartStatus window DEV={DEV} />}
      {stillCharging.length > 0 && (
        <div className="banner banner-warn" role="alert">
          <svg viewBox="0 0 16 16" width="16" height="16" style={{ flex: 'none', marginTop: 2 }} aria-hidden="true" fill="currentColor"><path d="M9.2 1 3.5 9h3.6L6.6 15l5.9-8.2H8.8z" /></svg>
          <div><b>{stillCharging.length} device{stillCharging.length === 1 ? ' is' : 's are'} still on the charger</b> — the cycle started at {hm(T.startMs)}:{' '}
            {stillCharging.map((sn, i) => <React.Fragment key={sn}>{i ? ', ' : ''}<button type="button" className="link-btn plain-link mono" onClick={() => focusDevice(sn)}>{sn}</button></React.Fragment>)}</div>
        </div>
      )}
      {!waiting && <div className="stat-row">
        {/* how long the devices have been running since they came off the charger, and how
            much of the planned cycle is left (to its end time on the Cycle plan) */}
        {T.charging ? <>
        <Metric label="Charging for" value={fmtDur(now - T.startMs)} delta={`on charge since ${when(T.startMs)} (median of ${charges.by.size} devices)`} />
        <Metric label="Battery" value={medNow != null ? <>{medNow}%<ChargeIcon state={chargeNow} /></> : '—'}
          delta={nows.length ? `median · range ${Math.min(...nows)}–${Math.max(...nows)}%` : 'no readings yet'} />
        <Metric label="Charge rate" value={chRate ? <>{chRate.toFixed(2)}<span className="secondary" style={{ fontSize: 13 }}> %/h</span></> : '—'}
          delta={chRate ? `${(chRate / 6).toFixed(2)}% per 10 min · median of ${chRates.length}` : 'needs 20 min on charge'} />
        <Metric label={`Reaches ${FULL}%`} value={etaFull ? <span style={{ whiteSpace: 'nowrap' }}>{hm(etaFull)}{dayKey(etaFull) !== todayKey() && <span className="secondary" style={{ fontSize: 12, fontWeight: 500 }}> {new Date(etaFull).toLocaleDateString([], { month: 'short', day: 'numeric' })}</span>}</span> : medNow != null && medNow >= FULL ? 'Done' : '—'}
          delta={etaFull ? `${fmtDur(etaFull - now)} from now` : `${full} of ${charges.by.size} devices at ${FULL}% or more`} />
        </> : <>
        {/* the big number is only the time (the user, 2 Nov 2026: "7h 02m · 7h 00m left" wrapped onto two lines);
            what is left, the end and the off-charger time go in the note, one per line */}
        <Metric label={ended ? 'Ran for' : 'Running for'}
          value={ended && runStart ? fmtDur(T.endMs - runStart) : runStart ? fmtDur(now - runStart) : 'Not started'}
          delta={ended && runStart && !T.tt?.span ? <>ended {hm(T.endMs)}<br />off charger {hm(runStart)}</>
            : T.running ? <>off charger {hm(runStart || T.startMs)}<br />no test planned yet</>
            : T.tt?.span ? <>{T.endMs > now ? `${fmtDur(T.endMs - now)} left · ends ${hm(T.endMs)}` : `ended ${hm(T.endMs)}`}</>
            : runStart ? <>{T.endMs > now ? `${fmtDur(T.endMs - now)} left · ends ${hm(T.endMs)}` : `planned end ${hm(T.endMs)} passed`}<br />off charger {hm(runStart)}</>
            : <>{started.length} of {all.length} devices off charger<br />planned {hm(T.startMs)} → {hm(T.endMs)}{T.overnight ? ' next day' : ''}</>} />
        <Metric label="Battery" value={medNow != null ? <>{medNow}%<ChargeIcon state={chargeNow} /></> : '—'}
          delta={nows.length ? `median · range ${Math.min(...nows)}–${Math.max(...nows)}%` : 'no readings yet'} />
        {/* one tile; its drop-down splits the drain by what the T7 was doing (the user, Oct 2026); not for a test that goes up and down */}
        {!T.tt?.span && <>
        <Stat label="Drain rate" value={rate ? <>{rate.toFixed(2)}<span className="secondary" style={{ fontSize: 13 }}> %/h</span></> : '—'}
          foot={rate ? `${(rate / 6).toFixed(2)}% per 10 min · median of ${rates.length}` : 'needs 20 min of running'}
          breakdownLabel="Drain with / without a load on the pad (ads run in both)" breakdownRight breakdownNoun="state"
          // two rows, not three: the T7s don't report wlc_charging (pad switched on), so "pad on, no load" and "pad off"
          // can't be told apart — the user, 2 Nov 2026: "b and c are the same"
          breakdown={[['active', 'WLC active'], ['none', 'WLC inactive']].map(([k, label]) => {
            const x = splitOf(k)
            return { id: k, label, value: x.rate ?? 0, display: x.rate ? `${x.rate.toFixed(2)} %/h` : '—',
              highlight: x.rate != null } // no description under the label (the user, 2 Nov 2026)
          })} />
        <Metric label={`Reaches ${END_BAND}%`} value={etaEnd ? <span style={{ whiteSpace: 'nowrap' }}>{hm(etaEnd)}{dayKey(etaEnd) !== key && <span className="secondary" style={{ fontSize: 12, fontWeight: 500 }}> {new Date(etaEnd).toLocaleDateString([], { month: 'short', day: 'numeric' })}</span>}</span> : medNow != null && medNow <= END_BAND ? 'Done' : '—'}
          delta={/* the time to 0 % too, at the bottom, also once 20 % is passed (the user, 2 Nov 2026) */
            etaEnd ? `${fmtDur(etaEnd - now)} from now${etaEmpty ? ` · 0 % ≈ ${when(etaEmpty)}` : ''}`
            : etaEmpty ? `Reaches 0 % ≈ ${when(etaEmpty)} · ${fmtDur(etaEmpty - now)} from now`
            : medNow != null && medNow <= 0 ? 'Reached 0 %'
            : medNow != null && medNow <= END_BAND ? 'Reaches 0 %: — (no drain rate yet)' : 'at the current rate'} />
        </>}
        </>}
        {/* a yellow border on a tile where some devices behave differently from the rest (the user, 27 Oct 2026) */}
        <Metric label="On track with plan" warn={!!T.tt && !T.tt.span && (drifting.length > 0 || silent > 0)} color={T.tt && !T.tt.span && conforming.length === T.serials.length ? 'var(--ok)' : drifting.length ? 'var(--warn)' : null}
          // no test named yet: nothing to be on track with, so "—", not a 0 that reads as every device failing (the user, 27 Oct 2026)
          value={!T.tt || T.tt.span ? '—' : <>{conforming.length}<span className="secondary" style={{ fontSize: 13 }}> / {T.serials.length}</span></>}
          delta={T.tt?.span ? 'charges and discharges by design' : !T.tt ? 'no test named yet · set it on the Cycle plan, or Auto names it from the readings' : drifting.length || silent
            ? [drifting.length && `${drifting.length} drifting`, silent && `${silent} not reporting`].filter(Boolean).join(' · ')
            : 'every device matches the declared test'} />
        {/* wireless charging: devices whose pad is active now (a load placed on it), from the
            latest check-in; the drop-down lists every device, active ones first and highlighted */}
        {(() => {
          // the cycle's devices only: one taken out of it leaves this count too
      const inCycle = new Set(T.serials)
      const rows = (T.serials.length ? DEV.filter(d => inCycle.has(d.serial)) : DEV).map(d => {
            const e = typeof d.snap?.extra === 'string' ? (() => { try { return JSON.parse(d.snap.extra) } catch (x) { return {} } })() : (d.snap?.extra || {})
            // wlc_status 1/2 = a load placed and being charged (seen during WLC on Load);
            // wlc_charging alone = the pad switched on, nothing on it
            const on = padLoad(e.wlc_status) === true, padOn = e.wlc_charging === true
            // WLC switched off reads wlc_status -1 at once (the pad flag lags minutes; 27 Oct 2026 experiment)
            const wlcOn = e.wlc_status != null && e.wlc_status !== '' ? +e.wlc_status !== -1 : padOn
            return { d, on, padOn, wlcOn, live: online(d) }
          })
          // the devices doing something different from the rest go on top, highlighted (the user, 27 Oct 2026:
          // "load not placed here"): with a load on most pads, the ones without; with most bare, the ones with
          const n = rows.filter(r => r.on).length, most = n * 2 >= rows.length
          rows.forEach(r => { r.odd = r.on !== most })
          rows.sort((a, b) => (b.odd - a.odd) || (b.on - a.on) || (b.padOn - a.padOn) || byBenchOrder(a.d.serial, b.d.serial))
          return <Stat label="WLC · load placed" warn={rows.some(r => r.odd)} value={<>{n}<span className="secondary" style={{ fontSize: 13 }}> / {rows.length}</span></>}
            foot={<>{(() => { const k = rows.filter(r => r.padOn && !r.on).length; return k ? `load on the pad · ${k} pad on, no load` : 'load on the pad' })()}
              {auto.wlc.length > 0 && <span className="auto-run" title="Running on the lab laptop — open the card to see or stop it"><br />⟳ {auto.wlc.join(' · ')}</span>}</>}
            breakdownLabel="WLC" breakdownRight breakdownWide breakdownNoun="device"
            breakdown={rows.map(r => ({ id: r.d.serial, label: r.d.serial, value: r.on ? 1 : 0, warn: r.odd,
              display: !r.wlcOn ? 'WLC off' : r.on ? 'Load placed' : r.padOn ? 'Pad on, no load' : 'No load', hint: r.live ? undefined : '· offline', onClick: () => focusDevice(r.d.serial),
              // WLC on / off on that T7 (the user, 2 Nov 2026)
              action: <WlcToggle serial={r.d.serial} enabled={r.wlcOn} /> }))}
            breakdownAction={<WlcToggleAll serials={rows.map(r => r.d.serial)} enabledCount={rows.filter(r => r.wlcOn).length} />} />
        })()}
        {/* the room's own temperature (the T7s report only their battery's): the lab's ESP32-S3 + SHT30,
            shown once a sensor has reported; range / average since the cycle started */}
        {roomDb.sensors?.length > 0 && (() => {
          const from = T.startMs && T.startMs < now ? T.startMs : now - 24 * H
          const rows = roomDb.sensors.map(x => ({ id: x.id, s: roomSummary(x.rows, from, now) })).filter(r => r.s).sort((a, b) => a.id < b.id ? -1 : 1)
          // the sensor sends over Wi-Fi (AIO-Office, 12 Nov 2026), or over the laptop's USB: say which to check
          const unplugged = roomDb.wifi?.lastAt ? ' · check its power and the AIO-Office Wi-Fi'
            : roomDb.usb && !roomDb.usb.open ? ' · not on Wi-Fi or the lab laptop\'s USB' : ''
          if (!rows.length) return <Metric label="Room temp" value="—" warn delta={`no reading in the last 24 h${unplugged || ' · check the sensor'}`} />
          const main = rows.find(r => !r.s.stale) || rows[0], s = main.s
          const since = T.startMs && T.startMs < now ? `since ${hm(from)}` : 'last 24 h'
          return <Stat label="Room temp" warn={s.stale}
            value={<><span style={s.stale ? { color: 'var(--status-critical)' } : undefined}>{s.t.toFixed(1)}</span><span className="secondary" style={{ fontSize: 13 }}> °C</span></>}
            foot={s.stale ? `sensor not heard from since ${when(s.at)}${unplugged}` : <>{s.rh != null ? `${s.rh}% RH · ` : ''}{s.min != null ? `${s.min.toFixed(1)}–${s.max.toFixed(1)} °C` : `at ${hm(s.at)}`}{s.min != null && <><br />avg {s.avg.toFixed(1)} {since}</>}</>}
            breakdownLabel="Room sensors" breakdownRight breakdownNoun="sensor"
            breakdown={rows.length > 1 ? rows.map(r => ({ id: r.id, label: r.id, value: r.s.t, display: `${r.s.t.toFixed(1)} °C${r.s.rh != null ? ` · ${r.s.rh}%` : ''}`,
              hint: r.s.stale ? `· not heard from since ${when(r.s.at)}` : `· ${hm(r.s.at)}`, highlight: r.s.stale })) : undefined} />
        })()}
        {/* the host app (the ads) on screen now, per device (MDM host-app list, every minute); devices on a
            client older than 1.11.0 do not report it */}
        {fleet.hostAppNow && (() => {
          const rows = T.serials.map(sn => ({ sn, x: fleet.hostAppNow.get(sn) })).map(r => ({ ...r, code: stateCode(r.x) }))
            .sort((a, b) => (a.code === SPAN.on) - (b.code === SPAN.on) || (a.sn < b.sn ? -1 : 1))
          const known = rows.filter(r => r.x), on = known.filter(r => r.code === SPAN.on).length, off = known.length - on
          if (!known.length) return null
          const wantAds = !!T.tt?.ads && !T.charging && !ended
          return <Stat label="Ads on screen" warn={off > 0 && (wantAds || off * 2 < known.length)} value={<><span style={wantAds && off ? { color: 'var(--status-critical)' } : undefined}>{on}</span><span className="secondary" style={{ fontSize: 13 }}> / {known.length}</span></>}
            foot={<>{off ? `${off} not showing the app${wantAds ? ' · ads stopped' : ''}` : 'the app in front on every device'}
              {auto.app.length > 0 && <span className="auto-run" title="Scheduled on the lab laptop — open the card to see or remove it"><br />⟳ {auto.app.join(' · ')}</span>}</>}
            breakdownLabel="Ads on screen" breakdownRight breakdownWide breakdownNoun="device"
            breakdownAction={<AppToggleAll serials={rows.map(r => r.sn)} onScreenCount={on} />}
            breakdown={rows.map(r => ({ id: r.sn, label: r.sn, value: r.code === SPAN.on ? 1 : 0, highlight: wantAds && r.x && r.code !== SPAN.on,
              // short states, so the serial is never cut off (the user, 30 Oct 2026: "Another app in front" hid it)
              display: r.x ? (r.code === SPAN.otherApp ? 'Other app' : SPAN_LABEL[r.code]) : 'Not reported',
              onClick: () => focusDevice(r.sn), // no "· since …" after the serial (the user, 30 Oct 2026: it only got cut off)
              // ▶ open / ■ close Nugget on that tablet (the user, 30 Oct 2026)
              action: <AppToggle serial={r.sn} onScreen={r.code === SPAN.on} /> }))} />
        })()}
      </div>}






      {!win.at ? (waiting ? null : <Stale win={win} n={DEV.length} />) : <>
        {/* after picking devices (a click in the list, or the Devices picker), one click back to all */}
        {picked != null && (
          <div className="pick-bar">
            <span>{picked.size === 0 ? 'No devices ticked'
              : picked.size <= 3 ? <>Showing only <b className="mono">{[...picked].join(', ')}</b></>
              : <>Showing <b>{picked.size}</b> of {sorted.length} devices</>}
              {/* the notes written on this device during this cycle, if any (the user, 12 Nov 2026) */}
              {only && <NotesIn serial={only} windows={[[T.startMs, Math.min(now, T.endMs ?? now)]]} />}</span>
            <button type="button" className="btn btn-sm" onClick={() => setPicked(null)}>× Clear selection</button>
          </div>
        )}
        {/* battery and temperature side by side; stacked again on narrow screens (.grid-2) */}
        <div className="grid grid-2" ref={chartsRef} style={{ scrollMarginTop: 80 }}>
        <div className="card">
          <div className="card-head"><div><h2>T7 battery, {T.charging ? 'charging' : ended ? 'last cycle' : 'today'}</h2><div className="card-sub">from {hm(chartFrom)} · live from MDM · every check-in</div></div>
            <Segmented ariaLabel="Battery chart" options={MODES} value={battMode} onChange={setBattMode} /></div>
          <div className="card-body">
            {picker}
            {/* what each line is, with swatches that match the lines drawn */}
            <div className="legend" style={{ margin: '8px 0 10px' }}>
              {battMode === 'avg' ? <>
                <span className="legend-item"><i className="legend-key-line" style={{ background: 'var(--series-1)' }} />Average battery of {shown.length} device{shown.length === 1 ? '' : 's'}</span>
                {/* a click shows that device alone (Every device); the serial is on hover */}
                {[[hi, 'Highest device', 'var(--series-8)'], [lo, 'Lowest device', 'var(--series-3)']].map(([c, name, color]) => (
                  <button key={name} type="button" className="legend-item clickable legend-btn" disabled={!c}
                    title={c ? `${c.serial} · ${lastOf(c)}% · click to show it alone` : undefined} onClick={() => c && focusDevice(c.serial)}>
                    <i className="legend-key-line" style={{ background: keyBackground(color, '3 3') }} />{name}</button>
                ))}
              </> : <>
                {drifting.length ? <span className="legend-item"><i className="legend-key-line" style={{ background: 'var(--status-warning)', height: 3 }} />Thicker line = not following the planned test</span> : null}
              </>}
            </div>
            {noneTicked ? <div className="empty">No devices ticked — pick some above, or choose Select all.</div> :
            <MultiLineChart series={series} h={230} yMax={100} yFmt={v => v + '%'} xFmt={hm} x0={chartFrom} x1={winTo}
              tip={battTip} />}
          </div>
        </div>
        <div className="card">
          <div className="card-head"><div><h2>Battery temperature, {T.charging ? 'charging' : ended ? 'last cycle' : 'today'}</h2><div className="card-sub">{shown.length} device{shown.length === 1 ? '' : 's'} · °C</div></div>
            <Segmented ariaLabel="Temperature chart" options={MODES} value={tempMode} onChange={setTempMode} /></div>
          <div className="card-body">
            {picker}
            <div className="legend" style={{ margin: '8px 0 10px' }}>
              {tempMode === 'avg' ? <>
                <span className="legend-item"><i className="legend-key-line" style={{ background: 'var(--series-1)' }} />Average temperature of {shown.length} device{shown.length === 1 ? '' : 's'}</span>
              </> : <span className="legend-item secondary">One line per device — each colour matches that device in the Devices list above. {few ? 'Each line ends with its device and temperature now.' : `The numbers at the right end mark devices at ${TEMP_WARN} °C or hotter now.`}</span>}
              {roomSeries.length ? <span className="legend-item" title="The lab's room sensor (SHT30), not a device"><i className="legend-key-line" style={{ background: keyBackground('var(--text-secondary)', '6 4') }} />Room temperature</span> : null}
            </div>
            {noneTicked ? <div className="empty">No devices ticked — pick some above, or choose Select all.</div> :
            <MultiLineChart h={230} yMax={60} yFmt={v => v.toFixed(0) + '°'} xFmt={hm} x0={chartFrom} x1={winTo}
              series={tempSeries}
              tip={tempTip} />}
          </div>
        </div>
        </div>
        <div className="card">
          {/* closed by default; a search opens it, since the search is about these rows */}
          <div className="card-head" role="button" tabIndex={0} aria-expanded={listShown} style={{ cursor: 'pointer' }}
            onClick={() => setListOpen(o => !o)} onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setListOpen(o => !o) } }}>
            <h2><span aria-hidden="true" style={{ display: 'inline-block', width: 16 }}>{listShown ? '▾' : '▸'}</span>Devices today ({conf.filter(c => matches(c.serial)).length})</h2>
            {/* the list's search sits in its title row, only while the list is open */}
            {listShown
              ? <span style={{ display: 'flex', alignItems: 'center', gap: 10 }} onClick={e => e.stopPropagation()} onKeyDown={e => e.stopPropagation()}>
                  <input className="control" type="search" placeholder="Search this list… (e.g. 044)" value={listQ} onChange={e => setListQ(e.target.value)} style={{ width: 240 }} aria-label="Search the device list" />
                  <span className="secondary">{reporting.length} reporting</span>
                </span>
              : <span className="secondary">{reporting.length} reporting · click to show every device — click one to chart it alone</span>}
          </div>
          {listShown && <div className="scroll-x"><SortTable head={[{ label: 'Device' }, { label: 'Against plan' }, ...(rebootCol ? [{ label: 'Reboots', className: 'r' }] : []), { label: 'Battery', className: 'r' }, { label: T.charging ? 'On charger' : 'Off charger', className: 'r' },
              { label: T.charging ? 'Charge rate' : 'Drain', className: 'r' },
              ...(padCols ? [{ label: 'Drain with WLC', className: 'r' }, { label: 'Drain without WLC', className: 'r' }] : []),
              ...(reachPct != null ? [{ label: `Reached ${reachPct} %`, className: 'r' }] : []),
              { label: 'Cycles', className: 'r' }, { label: 'Device temp now', className: 'r' },
              { label: 'Peak device temp', className: 'r' }, { label: `≥${TEMP_LIMIT} °C`, className: 'r' },
              ...(canOut ? [{ label: '', sortable: false }] : [])]}>
              {conf.filter(c => matches(c.serial) && c.serial.toLowerCase().includes(listQ.trim().toLowerCase())).sort((a, b) => byBenchOrder(a.serial, b.serial)).map(c => { // the lab's bench order (BENCH_ORDER); a heading click still sorts
                const r = runs.get(c.serial)
                const d = fleet.DMAP.get(c.serial); if (!d) return null
                const st = status(d), s = dayStats(c.serial, T.startMs), cs = T.tt?.span && c.state === 'untyped' ? ['pill-run', 'In test'] : CSTATE[c.state]
                const row = <tr key={c.serial} className={`row-link${only === c.serial ? ' is-selected' : ''}${stillSet.has(c.serial) ? ' row-warn' : ''}`} onClick={() => focusDevice(c.serial)}
                  title={only === c.serial ? 'Click to show every device again' : `Show only ${c.serial} in the charts above`}>
                  <td className="mono"><button type="button" className="link-btn plain-link mono" onClick={e => { e.stopPropagation(); focusDevice(c.serial) }}>{c.serial}</button></td>
                  <td><span className={`pill ${cs[0]}`}>{cs[1]}</span></td>
                  {rebootCol && <td className="r"><RebootCell decl={T.decl} serial={c.serial} onSaved={() => setPlanRev(v => v + 1)}>{T.decl.reboots?.[c.serial] ?? ''}</RebootCell>{/* the child is only for sorting by this column */}</td>}
                  <td className="r">{st.pct != null ? <span className="batt num">{st.pct}%<span className={`bar ${st.pct < 20 ? 'warn' : st.k === 'ready' ? 'ok' : 'run'}`}><i style={{ width: `${st.pct}%` }} /></span></span> : <span className="secondary">—</span>}</td>
                  {/* in a Charging Cycle: when it went on charge and how fast it gains (the user, 27 Oct 2026: it showed a negative drain) */}
                  {T.charging ? (() => { const ch = charges.by.get(c.serial), h = ch ? (ch.at - ch.t) / H : 0, g = ch && h >= 1 / 3 ? (ch.now - ch.pct) / h : null
                    return <><td className="r mono" title={ch ? `from ${ch.pct}% at ${hm(ch.t)}` : undefined}>{ch ? hm(ch.t) : <span className="secondary">not on charge</span>}</td>
                      <td className="r mono">{g != null ? `+${Math.max(0, g).toFixed(2)} %/h` : <span className="secondary">—</span>}</td></> })() : <>
                  <td className="r mono" title={r?.start?.firstOff ? `last check-in on charge ${new Date(r.start.after).toLocaleTimeString()} · first off charge ${new Date(r.start.firstOff).toLocaleTimeString()} — the MDM has no reading in between` : undefined}>
                    {stillSet.has(c.serial) ? <b style={{ color: 'var(--status-warning)' }}>still on charger</b> : r?.start ? hm(r.start.t) : <span className="secondary">{noStartText(rowsFor(c.serial))}</span>}
                    {r?.start?.firstOff && r.start.firstOff - r.start.t > 5 * MIN ? <span className="secondary" style={{ fontSize: 11 }}> – {hm(r.start.firstOff)}</span> : null}</td>
                  <td className="r mono" style={{ color: c.state === 'drifting' ? 'var(--warn)' : 'inherit' }}>{r?.rate != null ? r.rate.toFixed(2) + ' %/h' : <span className="secondary">—</span>}</td>
                  {padCols && <><td className="r mono" title="since it left the charger, over the time with a load on the pad (under 20 min = —)">{r?.split?.active != null ? r.split.active.toFixed(2) + ' %/h' : <span className="secondary">—</span>}</td>
                    <td className="r mono" title="since it left the charger, over the time with no load on the pad (under 20 min = —)">{r?.split?.none != null ? r.split.none.toFixed(2) + ' %/h' : <span className="secondary">—</span>}</td></>}</>}
                  {reachPct != null && (() => { const t = reachAt(r); return <td className="r mono" title={t ? `first reading at ${reachPct} % or less since it left the charger · WLC is switched off then` : `not at ${reachPct} % yet`}>{t ? when(t) : <span className="secondary">—</span>}</td> })()}
                  <td className="r mono">{fmtLifetime(lifetimeCycles(d.snap))}</td>
                  <td className="r mono" style={{ color: online(d) && d.snap.battery_temp_c >= TEMP_LIMIT ? 'var(--bad)' : online(d) && d.snap.battery_temp_c >= TEMP_WARN ? 'var(--warn)' : 'inherit' }}>{online(d) && d.snap.battery_temp_c ? d.snap.battery_temp_c.toFixed(1) + ' °C' : <span className="secondary">—</span>}</td>
                  <td className="r mono" style={{ color: s?.maxTemp >= TEMP_LIMIT ? 'var(--bad)' : s?.maxTemp >= TEMP_WARN ? 'var(--warn)' : 'inherit' }}>{s?.maxTemp != null ? s.maxTemp.toFixed(1) + ' °C' : <span className="secondary">—</span>}</td>
                  <td className="r mono" style={{ color: s?.minAbove45 ? 'var(--bad)' : 'inherit' }}>{s?.minAbove45 ? fmtDur(s.minAbove45 * MIN) : <span className="secondary">—</span>}</td>
                  {canOut && <td className="r"><button type="button" className="btn btn-sm" title={`Take ${c.serial} out of this cycle, with a reason`}
                    onClick={e => { e.stopPropagation(); setTakingOut(t => t === c.serial ? null : c.serial) }}>{takingOut === c.serial ? 'Cancel' : 'Take out'}</button></td>}
                </tr>
                // the take-out form opens right under its device, as part of the table
                return takingOut === c.serial && canOut ? [row,
                  <tr key={c.serial + ':out'} data-attached="1" className="takeout-row"><td colSpan={(padCols ? 12 : 10) + (reachPct != null ? 1 : 0)}>
                    <TakeOutForm serial={c.serial} cycle={T} onCancel={() => setTakingOut(null)}
                      onSave={rec => { if (T.decl) takeOut(GROUP, T.decl.id, { serial: c.serial, ...rec }); else setPendingOut(T.key, c.serial, rec); setTakingOut(null); setPlanRev(v => v + 1) }} />
                  </td></tr>] : row
              })}
          </SortTable></div>}
        </div>
        {canOut && T.removed?.length > 0 && (
          <div className="card">
            {/* a drop-down like Devices today, closed by default (the user, 27 Oct 2026) */}
            <div className="card-head" role="button" tabIndex={0} aria-expanded={outOpen} style={{ cursor: 'pointer' }}
              onClick={() => setOutOpen(o => !o)} onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setOutOpen(o => !o) } }}>
              <h2><span aria-hidden="true" style={{ display: 'inline-block', width: 16 }}>{outOpen ? '▾' : '▸'}</span>Taken out of this cycle ({T.removed.length})</h2>
              <span className="secondary">kept on record · {T.decl ? `their cycles from then on don't count toward ${T.tt?.name}` : 'held until the test is named, then put on the cycle'}</span></div>
            {outOpen && <div className="scroll-x"><SortTable head={[{ label: 'Device' }, { label: 'Taken out' }, { label: 'Reason' }, { label: 'Note' }, { label: 'By' }, { label: '', sortable: false }]}>
              {/* a click shows the device alone in the charts above, as in Devices today (the user, 27 Oct 2026) */}
              {T.removed.map(r => (
                <tr key={r.serial} className={`row-link${only === r.serial ? ' is-selected' : ''}`} onClick={() => focusDevice(r.serial)}
                  title={only === r.serial ? 'Click to show every device again' : `Show only ${r.serial} in the charts above`}>
                  <td className="mono"><button type="button" className="link-btn plain-link mono" onClick={e => { e.stopPropagation(); focusDevice(r.serial) }}>{r.serial}</button></td>
                  <td className="mono">{dayKey(r.at) === todayKey() ? hm(r.at) : dt(r.at)}</td>
                  <td>{r.reason}</td>
                  <td>{r.note || <span className="secondary">—</span>}</td>
                  <td>{r.by || <span className="secondary">—</span>}</td>
                  {/* two clicks, no browser pop-up (4 Nov 2026: a browser set to block this site's dialogs made confirm() say no
                      without asking, so Put back did nothing): the first arms it for 5 s, the second puts it back */}
                  <td className="r"><button type="button" className={`btn btn-sm${putting === r.serial ? ' btn-warn' : ''}`}
                    title={`Put ${r.serial} back into this cycle (the record of it being taken out is removed)`}
                    onClick={e => { e.stopPropagation()
                      if (putting !== r.serial) { setPutting(r.serial); clearTimeout(putTimer.current); putTimer.current = setTimeout(() => setPutting(null), 5000); return }
                      setPutting(null); if (T.decl) putBack(GROUP, T.decl.id, r.serial); else setPendingOut(T.key, r.serial, null); setPlanRev(v => v + 1) }}>
                    {putting === r.serial ? 'Click again to put back' : 'Put back'}</button></td>
                </tr>
              ))}
            </SortTable></div>}
          </div>
        )}
        {/* the iPhones, last on the page (the user, 31 Oct 2026): each one's battery always (13 Nov 2026), and in a discharge cycle the
            hourly table of an iPhone on the pad in place of the load (the lab, 27 Oct 2026), one card */}
        {!side && (T.charging || !(T.running || T.decl)) && <IphonesNow now={now} />}
        {!side && !T.charging && (T.running || T.decl) && <PhoneOnPad day={T.key} start={Math.round(chartFrom / 60e3) * 60e3} end={T.endMs} serials={T.serials} now={now} ownStart={sn => runs.get(sn)?.start?.t ?? null} maxHours={T.tt?.loadHours ?? null} />}
      </>}
    </div>
  )
}

// Off charger with no run timed (no cycle running): "still full" only when it is (the user, 6 Nov 2026: devices at 13 % read "still full")
const noStartText = rows => { const last = rows?.[rows.length - 1]
  if (!last || Date.now() - Date.parse(last.timestamp) > 15 * MIN) return '—'
  return last.extra?.charging ? 'on charge' : last.battery_pct >= 98 ? 'still full' : '—' }

// plan.js stores per cycles-group; these keep the group name in one place.
const DECLS = () => loadDecls(GROUP)
const ROTA = () => loadRota(GROUP)

const Metric = ({ label, value, delta, color, warn }) => (
  <div className={`stat${warn ? ' is-warn' : ''}`}>
    <div className="stat-label">{label}</div>
    <div className="stat-value" style={color ? { color } : undefined}>{value}</div>
    <div className="stat-foot">{delta}</div>
  </div>
)
const Stale = ({ win, n }) => (
  <div className="banner">
    <svg viewBox="0 0 16 16" width="16" height="16" style={{ flex: "none", marginTop: 2 }} aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.5"><circle cx="8" cy="8" r="6.5" /><path d="M8 7v4M8 5h.01" /></svg>
    <div>{win.loading ? <><span className="spin" /> Reading the last {WINDOW_HOURS} h of history for {n} devices…</> : win.err ? `Could not read recent history: ${win.err}` : 'No recent history loaded yet.'}</div>
  </div>
)
function DeviceDay({ d, from }) {
  const s = dayStats(d.serial, from), st = status(d)
  return <>
    <h3 className="mono">{d.serial}</h3>
    <div className="sub">{(d.snap?.device_class || 'device').toUpperCase()} · {st.label} · seen {ago(Date.parse(d.snap.last_seen_at))}</div>
    <div className="big num">{st.pct != null ? st.pct + '%' : '—'}<small>{online(d) && d.snap.battery_temp_c ? d.snap.battery_temp_c.toFixed(1) + ' °C now' : st.label.toLowerCase()}</small></div>
    {!s ? <div className="empty-note">No readings in this window.</div> : <>
      <hr /><h4>Today</h4>
      <dl className="kv">
        <dt>At window start</dt><dd className="mono">{s.startPct}%</dd>
        <dt>Drained</dt><dd className="mono">{s.drained.toFixed(0)}%</dd>
        <dt>Peak temperature</dt><dd className="mono" style={{ color: s.maxTemp >= TEMP_LIMIT ? 'var(--bad)' : s.maxTemp >= TEMP_WARN ? 'var(--warn)' : 'inherit' }}>{s.maxTemp != null ? s.maxTemp.toFixed(1) + ' °C' : '—'}</dd>
        <dt>Average temperature</dt><dd className="mono">{s.avgTemp != null ? s.avgTemp.toFixed(1) + ' °C' : '—'}</dd>
        <dt>Over {TEMP_LIMIT} °C</dt><dd className="mono" style={{ color: s.minAbove45 ? 'var(--bad)' : 'inherit' }}>{s.minAbove45 ? fmtDur(s.minAbove45 * MIN) : '—'}</dd>
        <dt>Samples</dt><dd className="mono">{s.n}</dd>
      </dl>
    </>}
  </>
}
// Devices whose readings since the cycle started don't look like the planned test: a
// discharge test wants the battery down at least 3 points and off the charger, a charging
// test the battery up 3 or on charge (window.js conform). Each row says which part failed.
function Drifters({ drifting, tt }) {
  const why = c => {
    if (tt?.expect === 'charge') return `battery ${c.delta >= 0 ? 'up' : 'down'} only ${Math.abs(c.delta)}% and not charging`
    if (c.charging) return c.delta <= -3 ? `on the charger now (battery ${c.delta}%)` : `on the charger — battery ${c.delta > 0 ? '+' : ''}${c.delta}% since the start`
    return c.delta > 0 ? `battery went up ${c.delta}% — expected it to drain` : `battery moved only ${c.delta}% — expected at least a 3% drop`
  }
  return (
    <div className="card">
      <div className="card-head"><h3>Drifting — not behaving like {tt ? tt.name : 'the planned test'}</h3><span className="card-sub">{drifting.length} device{drifting.length === 1 ? '' : 's'}</span></div>
      {drifting.length ? <>
        {drifting.map(c => (
          <div className="row-item" key={c.serial}>
            <span className="mono">{c.serial}</span>
            <span className="grow secondary" style={{ fontSize: 12.5 }}>{why(c)}</span>
            <span className="mono" style={{ color: 'var(--status-warning)' }}>{(c.delta > 0 ? '+' : '') + c.delta}%</span>
          </div>
        ))}
        <div className="card-body"><div className="help">Checked from the cycle's start: a {tt?.expect === 'charge' ? 'charging test expects the battery to rise at least 3% or the device to be charging' : 'discharge test expects the battery to drop at least 3% with the device off the charger'}. Often it just means the device hasn't been taken off (or put on) charge yet. If it has been taken away, use Take out in the device list.</div></div>
      </> : <div className="empty">{tt ? 'Every reporting device matches the planned test.' : 'Nothing planned for today, so nothing can drift.'}</div>}
    </div>
  )
}

// T7's own device picker markup (chart-legend-details / series-legend), so it looks and
// behaves like the one on the Overview's single-test view. Drifting devices are marked.
function DevicePicker({ serials, picked, colorOf, styleOf, drifting, onToggle, onAll, onNone, onSet }) {
  const n = picked == null ? serials.length : picked.size
  const [q, setQ] = useState('')
  const shown = serials.filter(sn => sn.toLowerCase().includes(q.trim().toLowerCase()))
  const ticked = new Set(picked ?? serials)
  // with a search typed, Select all / Clear all act on the serials it shows
  const selectShown = () => q.trim() ? onSet(new Set([...ticked, ...shown])) : onAll()
  const clearShown = () => { if (!q.trim()) return onNone(); const n2 = new Set(ticked); shown.forEach(sn => n2.delete(sn)); onSet(n2) }
  return (
    <details className="chart-legend-details">
      <summary>Devices ({n}/{serials.length})</summary>
      <div className="series-legend-actions">
        <input className="control" type="search" placeholder="Search serials… (e.g. 044)" value={q} onChange={e => setQ(e.target.value)} style={{ flex: '1 1 200px', maxWidth: 280 }} />
        <button type="button" className="btn" onClick={selectShown}>Select all</button>
        <button type="button" className="btn" onClick={clearShown}>Clear all</button>
      </div>
      <div className="legend series-legend" role="group" aria-label="Devices to show on the charts">
        {shown.length ? shown.map(sn => (
          <label className="series-legend-item" key={sn}>
            <input type="checkbox" checked={picked == null || picked.has(sn)} onChange={() => onToggle(sn)} />
            <span className="legend-key-line" style={{ background: keyBackground(colorOf.get(sn), styleOf.get(sn)?.dash) }} aria-hidden="true" />
            <span>{sn}{drifting.has(sn) ? <span className="secondary"> · drifting</span> : null}</span>
          </label>
        )) : <span className="secondary">No serial matches “{q.trim()}”.</span>}
      </div>
    </details>
  )
}


// Taking one device out of the running cycle: a reason from a short list, an optional
// note and name. Saved on the cycle with the time, so the record says who left and why. A
// reason typed under "Other" is saved as that reason, and offered in the list from then on.
function TakeOutForm({ serial, cycle, onSave, onCancel }) {
  const reasons = takeOutReasons()
  const [reason, setReason] = useState(reasons[0])
  const [note, setNote] = useState('')
  const [by, setBy] = useState(() => { try { return localStorage.getItem('declaredBy') || '' } catch (e) { return '' } })
  const needNote = reason === 'Other' && !note.trim()
  return (
    <div className="card-body takeout">
      <div style={{ marginBottom: 8 }}><b>Take <span className="mono">{serial}</span> out of {cycle.tt?.name || 'this cycle'}</b>
        <div className="secondary" style={{ fontSize: 12 }}>It leaves the charts and the cycle from now ({hm(Date.now())}). The run it is on stops counting toward this test.{!cycle.decl ? ' The test isn\'t named yet: this is kept and goes onto the cycle once it is.' : ''}</div></div>
      <div className="takeout-grid">
        <label className="field"><span>Reason</span>
          <span className="ver" style={{ display: 'block' }}><select value={reason} onChange={e => setReason(e.target.value)} style={{ width: '100%' }}>
            {reasons.map(r => <option key={r}>{r}</option>)}</select></span></label>
        <label className="field"><span>{reason === 'Other' ? 'Reason (required, kept for next time)' : 'Note (optional)'}</span>
          <input className="input" value={note} onChange={e => setNote(e.target.value)} placeholder={reason === 'Other' ? 'e.g. testing v2.1.031' : 'e.g. taken by Sam for the customer demo'} /></label>
        <label className="field"><span>Taken out by</span>
          <input className="input" value={by} onChange={e => setBy(e.target.value)} placeholder="optional" /></label>
      </div>
      <div className="form-actions">
        <button className="btn" onClick={onCancel}>Cancel</button>
        <button className="btn btn-primary" disabled={needNote} title={needNote ? 'Add a note for "Other"' : undefined}
          onClick={() => { try { localStorage.setItem('declaredBy', by) } catch (e) {} onSave({ reason, note: note.trim(), by: by.trim() }) }}>Take out</button>
      </div>
    </div>
  )
}

// A note kept on the cycle (the user, 29 Oct 2026: "just for the record" — which devices had the load
// for the first 3 h and which with a 30-min gap). Saved on the plan entry, so every browser and the
// test screen see it.
// Before the cycle's test is known it takes `note` / `onSave` instead (held in data/phone.json, moved onto the entry later).
/** The lab's reboot count for one device in this cycle: click to type it, Enter or leaving the box saves (shared through the plan). */
function RebootCell({ decl, serial, onSaved }) {
  const cur = decl.reboots?.[serial]
  const [editing, setEditing] = useState(false)
  const [text, setText] = useState('')
  const save = () => {
    const v = text.trim(), n = v === '' ? null : Number(v)
    if (v === '' || Number.isInteger(n)) { if (n !== (cur ?? null)) { setReboots(GROUP, decl.id, serial, n); onSaved() } }
    setEditing(false)
  }
  if (editing) return <input className="reboot-input mono" autoFocus inputMode="numeric" value={text} aria-label={`Reboots of ${serial}`}
    onChange={e => setText(e.target.value.replace(/[^0-9]/g, '').slice(0, 3))} onBlur={save}
    onKeyDown={e => { if (e.key === 'Enter') save(); if (e.key === 'Escape') setEditing(false) }} onClick={e => e.stopPropagation()} />
  return <button type="button" className="link-btn plain-link mono reboot-btn" title={`Times ${serial} was rebooted in this cycle · click to change`}
    onClick={e => { e.stopPropagation(); setText(cur != null ? String(cur) : ''); setEditing(true) }}>{cur != null ? cur : '—'}</button>
}

function CycleNote({ decl, note, onSave, onSaved }) {
  const cur = decl ? decl.note || '' : note || ''
  const [editing, setEditing] = useState(false)
  const [text, setText] = useState(cur)
  useEffect(() => { if (!editing) setText(cur) }, [cur])
  const save = () => { if (decl) setCycleNote(GROUP, decl.id, text); else onSave(text); setEditing(false); onSaved() }
  if (editing) return (
    <div className="cycle-note-edit">
      <textarea className="input" rows={2} autoFocus value={text} onChange={e => setText(e.target.value)} placeholder="e.g. 064, 280: load the first 3 h; the rest: load with a 30-min gap" />
      <span style={{ display: 'flex', gap: 6 }}><button type="button" className="btn btn-sm btn-primary" onClick={save}>Save note</button>
        <button type="button" className="btn btn-sm" onClick={() => { setText(cur); setEditing(false) }}>Cancel</button></span>
    </div>)
  return cur
    ? <div className="cycle-note" style={{ marginTop: 8, cursor: 'default', whiteSpace: 'pre-line' }}><b>Note</b> {cur} <button type="button" className="link-btn" onClick={() => setEditing(true)}>✎ edit</button></div>
    : <button type="button" className="link-btn" style={{ marginTop: 6, fontSize: 12.5 }} onClick={() => setEditing(true)}>+ Add a note to this cycle</button>
}
